style:
:host{color-scheme:only light;
 --paper:#FBF9F4; --ink:#1C2B30; --muted:#6B7C82; --line:#DFE3E0;
 --teal:#0E7B85; --teal2:#0E4B54; --amber:#C9902A; --sheet:#fff;
 --fs:17px;
}
:host([data-theme=night]){--paper:#0B1417;--ink:#DDE7E9;--muted:#8AA0A6;--line:#1E2E33;
 --teal:#4FC2CE;--teal2:#7FD8E2;--sheet:#0F1B1F;}
*{box-sizing:border-box}
.bshell{overscroll-behavior:contain}
.bshell{margin:0;background:var(--paper);color:var(--ink);
 font-family:'Lora',Georgia,serif;font-size:var(--fs);line-height:1.6;
 -webkit-text-size-adjust:100%;-webkit-tap-highlight-color:transparent}
h1,h2,h3,h4,.ui,.un,.tn,.qn,.pn,.btn,.ipa,.kick,th,.nk{font-family:'Be Vietnam Pro',system-ui,sans-serif}
::-webkit-scrollbar{width:0;height:0}
*:focus{outline:none}

/* ---------- khung sách ---------- */
#book{display:flex;height:var(--bh);overflow-x:auto;overflow-y:hidden;
 scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;touch-action:pan-x}
.bshell.ink #book{touch-action:none;overflow-x:hidden}
.page{position:relative;flex:0 0 100%;height:var(--bh);scroll-snap-align:center;scroll-snap-stop:always;
 padding:48px 0 0}
.sheet{position:absolute;inset:44px 0 42px;overflow-y:auto;
 -webkit-overflow-scrolling:touch;padding:26px clamp(20px,6vw,64px) 40px;max-width:52rem;margin:0 auto;
 background:var(--sheet);border-left:1px solid var(--line);border-right:1px solid var(--line)}
.bshell.ink .sheet{overflow:hidden}
canvas.ink{position:absolute;inset:44px 0 42px;
 max-width:52rem;margin:0 auto;pointer-events:none;touch-action:none}
.bshell.ink canvas.ink{pointer-events:auto}
.pfoot{position:absolute;left:0;right:0;bottom:0;height:42px;display:flex;align-items:center;
 justify-content:space-between;padding:0 clamp(18px,5vw,60px);max-width:52rem;margin:0 auto;
 font-family:'Be Vietnam Pro',sans-serif;font-size:.6rem;letter-spacing:.16em;color:var(--muted);
 border-top:1px solid var(--line)}
.pn{color:var(--teal)}

/* ---------- thanh trên ---------- */
.bar{position:absolute;top:0;left:0;right:0;height:44px;z-index:40;
 display:flex;align-items:center;gap:6px;padding:0 12px;
 background:color-mix(in srgb,var(--paper) 94%,transparent);backdrop-filter:blur(12px);
 border-bottom:1px solid var(--line)}
.btn,.ui{font-family:'Be Vietnam Pro',sans-serif;font-size:11px;font-weight:600;letter-spacing:.06em;
 color:var(--ink);background:transparent;border:1px solid var(--line);border-radius:999px;
 padding:7px 11px;min-height:32px;cursor:pointer;white-space:nowrap}
.ui.on,.btn.on{background:var(--teal);border-color:var(--teal);color:#fff}
.btn.ghost{color:var(--muted)}
.bar .title{flex:1;min-width:0;font-family:'Be Vietnam Pro',sans-serif;font-size:10.5px;letter-spacing:.14em;
 text-transform:uppercase;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.prog{position:absolute;top:0;left:0;height:2px;background:var(--teal);width:0;z-index:60;transition:width .2s}

/* ---------- công cụ bút ---------- */
.pentools{position:absolute;right:12px;bottom:56px;z-index:45;
 display:none;flex-direction:column;gap:8px;background:var(--sheet);border:1px solid var(--line);
 border-radius:999px;padding:10px 8px;box-shadow:0 10px 30px rgba(0,0,0,.12)}
.bshell.ink .pentools{display:flex}
.sw{width:26px;height:26px;border-radius:50%;border:2px solid transparent;cursor:pointer}
.sw.on{border-color:var(--ink)}
.pentools button{width:30px;height:30px;border-radius:50%;border:1px solid var(--line);background:transparent;
 font-size:13px;cursor:pointer;color:var(--ink)}

/* ---------- nội dung ---------- */
.coverpage{text-align:center;padding:8vh 0 0}
.kick{font-family:'Be Vietnam Pro',sans-serif;font-size:.6rem;letter-spacing:.42em;color:var(--teal)}
.coverpage h1{font-weight:400;letter-spacing:.14em;font-size:clamp(2.2rem,9vw,3.6rem);margin:1.2rem 0 0;line-height:1.1}
.coverpage h1 em{font-style:normal;color:var(--teal)}
.coverpage .sub{font-family:'Be Vietnam Pro',sans-serif;font-size:.82rem;color:var(--muted);margin-top:1.6rem;line-height:1.8}
.coverpage .sub i{font-style:normal;opacity:.75}
.cvline{width:64px;height:2px;background:var(--amber);margin:2.4rem auto}
.coverpage .note{font-family:'Be Vietnam Pro',sans-serif;font-size:.7rem;color:var(--muted);line-height:1.9}
.ph{font-family:'Be Vietnam Pro',sans-serif;font-size:1rem;font-weight:800;letter-spacing:.24em;color:var(--teal2);
 border-bottom:2px solid var(--teal);padding-bottom:10px;margin:0 0 22px;display:flex;gap:10px;align-items:baseline}
.ph i{font-style:normal;font-weight:400;font-size:.66rem;letter-spacing:.1em;color:var(--muted)}
.toc{list-style:none;margin:0;padding:0}
.toc li{display:flex;gap:14px;padding:11px 0;border-bottom:1px solid var(--line)}
.tn{font-family:'Be Vietnam Pro',sans-serif;font-size:.6rem;letter-spacing:.14em;color:var(--teal);flex:0 0 5.2rem;padding-top:.3em}
.tt{font-family:'Be Vietnam Pro',sans-serif;font-size:.92rem;font-weight:600}
.tt i{display:block;font-style:normal;font-weight:400;font-size:.72rem;color:var(--muted);margin-top:2px}
.howto{margin-top:26px;border:1px solid var(--line);border-left:3px solid var(--amber);border-radius:6px;padding:14px 16px;
 font-size:.9rem}
.howto b{font-family:'Be Vietnam Pro',sans-serif;font-size:.78rem;letter-spacing:.1em;color:var(--teal2)}
.howto p{margin:.5em 0 0;color:var(--muted)}
.uhead{margin-bottom:18px}
.un{font-family:'Be Vietnam Pro',sans-serif;font-size:.6rem;font-weight:800;letter-spacing:.28em;color:var(--amber)}
.uhead h2{font-family:'Be Vietnam Pro',sans-serif;font-weight:800;font-size:clamp(1.25rem,4.4vw,1.7rem);
 margin:.5rem 0 .2rem;line-height:1.2}
.uhead i{font-style:normal;font-family:'Be Vietnam Pro',sans-serif;font-size:.76rem;color:var(--muted)}
.uhead.sm h2{font-size:1.15rem}
.lead{color:var(--muted);font-size:.95rem;margin:0 0 20px}
.gt,.vset{margin-bottom:18px;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.gt h4,.vset h4{margin:0;font-size:.68rem;font-weight:800;letter-spacing:.16em;background:var(--teal);color:#fff;
 padding:8px 12px}
.gt table,.vset table,.vt{width:100%;border-collapse:collapse;font-size:.9rem}
.gt td,.vset td{padding:9px 12px;border-top:1px solid var(--line);vertical-align:top}
td.k{width:34%;font-family:'Be Vietnam Pro',sans-serif;font-size:.8rem;color:var(--teal2);font-weight:600}
.hints{border:1px solid var(--line);border-left:3px solid var(--amber);border-radius:6px;padding:12px 16px}
.hints h4{margin:0 0 8px;font-size:.68rem;letter-spacing:.16em;color:var(--amber)}
.hints h4 i{font-style:normal;color:var(--muted);font-weight:400;margin-left:8px}
.hints ul{margin:0;padding-left:1.1em}
.hints li{margin-bottom:7px;font-size:.88rem;color:var(--muted)}
.hints b,.gt b{color:var(--ink);font-weight:600}
.vt th{font-size:.62rem;letter-spacing:.12em;color:var(--muted);text-align:left;padding:0 10px 8px;border-bottom:2px solid var(--teal)}
.vt td{padding:9px 10px;border-bottom:1px solid var(--line);vertical-align:top;font-size:.88rem}
td.w{font-family:'Be Vietnam Pro',sans-serif;font-weight:600;white-space:nowrap}
td.ipa{color:var(--teal);font-size:.78rem;white-space:nowrap}
td.vn{color:var(--muted)}
td.exm{font-style:italic;font-size:.82rem}
w{cursor:pointer;border-bottom:1px dotted var(--teal)}
w.hit{background:var(--teal);color:#fff}
.ex h3{font-family:'Be Vietnam Pro',sans-serif;font-size:.8rem;font-weight:800;letter-spacing:.1em;
 color:var(--teal2);margin:0 0 14px}
.ex h3 i{font-style:normal;font-weight:400;color:var(--muted);margin-left:8px;font-size:.72rem}
.qs{list-style:none;margin:0;padding:0}
.qs li{display:flex;gap:10px;align-items:baseline;padding:10px 0;border-bottom:1px dashed var(--line)}
.qn{font-family:'Be Vietnam Pro',sans-serif;font-size:.62rem;color:var(--muted);flex:0 0 1.8rem}
.qt{flex:1}
input.gap{font-family:'Be Vietnam Pro',sans-serif;font-size:.88rem;border:0;border-bottom:1.5px solid var(--teal);
 background:transparent;color:var(--ink);width:8.5rem;padding:2px 4px;text-align:center}
input.gap.ok{border-color:#1F9D55;color:#1F9D55}
input.gap.no{border-color:#C0524A;color:#C0524A}
.ck{font-size:.9rem;width:1.2rem;text-align:center}
.exbar{display:flex;gap:8px;align-items:center;margin-top:16px}
.score{font-family:'Be Vietnam Pro',sans-serif;font-size:.74rem;color:var(--teal)}
.keys{columns:2;column-gap:26px}
.kb{break-inside:avoid;margin-bottom:16px}
.kb h4{font-family:'Be Vietnam Pro',sans-serif;font-size:.66rem;letter-spacing:.12em;color:var(--teal2);margin:0 0 6px}
.key{list-style:none;margin:0;padding:0;font-size:.82rem}
.key li{display:flex;gap:8px;padding:2px 0}
.tiny{font-family:'Be Vietnam Pro',sans-serif;font-size:.7rem;color:var(--muted);margin-top:14px}

/* ---------- mục lục trượt ---------- */
.scrim{position:absolute;inset:0;background:rgba(0,0,0,.4);opacity:0;pointer-events:none;transition:opacity .3s;z-index:70}
.scrim.show{opacity:1;pointer-events:auto}
.toc-drawer{position:absolute;inset:0 auto 0 0;width:min(86vw,22rem);z-index:80;background:var(--sheet);
 border-right:1px solid var(--line);transform:translateX(-101%);transition:transform .3s cubic-bezier(.3,.8,.3,1);
 overflow-y:auto;padding:calc(20px + env(safe-area-inset-top)) 0 40px}
.toc-drawer.show{transform:none}
.toc-drawer h4{font-family:'Be Vietnam Pro',sans-serif;font-size:.58rem;letter-spacing:.26em;color:var(--muted);
 margin:0 0 12px;padding:0 18px}
.toc-drawer ul{list-style:none;margin:0;padding:0}
.toc-drawer a{display:flex;gap:10px;padding:9px 18px;color:var(--ink);text-decoration:none;cursor:pointer;
 border-left:2px solid transparent;font-family:'Be Vietnam Pro',sans-serif;font-size:.82rem}
.toc-drawer a.here{background:color-mix(in srgb,var(--teal) 10%,transparent);border-left-color:var(--teal)}
.nk{font-size:.58rem;color:var(--teal);flex:0 0 3rem;padding-top:.25em}

@media print{
 .bar,.pentools,.toc-drawer,.scrim,.prog,canvas.ink,.exbar{display:none!important}
 #book{display:block;height:auto;overflow:visible}
 .page{height:auto;page-break-after:always;padding:0}
 .sheet{position:static;inset:auto;border:0;padding:0 0 10mm;overflow:visible}
 .pfoot{position:static;border:0}
 input.gap{border-bottom:1px solid #999}
 @page{margin:16mm 14mm}
}
@media(prefers-reduced-motion:reduce){*{transition:none!important}}
